/* ================== PARAMETERS (SSMS) ================== */
DECLARE @WO_Num   INT = 0;              -- Mã Lệnh sản xuất (U_belnrid), 0: không lọc
DECLARE @WO_Pos   INT = 0;              -- Vị trí Lệnh sản xuất (U_belposid), 0: không lọc
DECLARE @ItemCode NVARCHAR(50) = '';    -- Mã vật tư (itemcode), '': không lọc
select t0.docdate ,t3.DistNumber, t0.Quantity, t0.docentry, t0.itemcode, 'Nhap'as Loai from IGN1 t0inner join OITL t1 on t0.DocEntry = t1.DocEntry and t1.DocType = 59inner join ITL1 t2 on t1.LogEntry = t2.LogEntryinner join OBTN t3 on t2.ItemCode = t3.ItemCode and t2.SysNumber = t3.SysNumberwhere (t0.U_belnrid = @WO_Num OR @WO_Num = 0) and (t0.U_belposid = @WO_Pos OR @WO_Pos = 0) and (t0.itemcode = @ItemCode OR @ItemCode = '')union allselect t0.docdate, t3.DistNumber, - t0.Quantity, t0.docentry, t0.itemcode, 'Xuat'as Loai from IGE1 t0inner join OITL t1 on t0.DocEntry = t1.DocEntry and t1.DocType = 60inner join ITL1 t2 on t1.LogEntry = t2.LogEntryinner join OBTN t3 on t2.ItemCode = t3.ItemCode and t2.SysNumber = t3.SysNumberwhere (t0.U_belnrid = @WO_Num OR @WO_Num = 0) and (t0.U_belposid = @WO_Pos OR @WO_Pos = 0) and (t0.itemcode = @ItemCode OR @ItemCode = '')order by t3.DistNumber